#include <stdio.h>

double average(const double *start, const double *end)
{
    double total = 0;
    int count = 0;
    for (const double *p = start; p < end; p++) {
        total += *p;
        count++;
    }
    return count ? total / count : 0;
}

void show_size(const double a[])
{
    printf("inside the function, sizeof(a) is %zu (just a pointer)\n", sizeof(a));
}

int main(void)
{
    double temps[5] = {18.5, 22.0, 31.0, 25.5, 40.0};
    printf("the array is %zu bytes\n", sizeof(temps));
    show_size(temps);
    printf("average of all: %.1f\n", average(temps, temps + 5));
    printf("average of the middle three: %.1f\n", average(temps + 1, temps + 4));
    double *p = temps;
    printf("*(p + 2) is %.1f, same as temps[2]\n", *(p + 2));
    return 0;
}

