int sum_readings(const int *p, int n)
{
    int total = 0;
    /* walk p along the readings */
    return total;
}

exercises.solution:
int sum_readings(const int *p, int n)
{
    int total = 0;
    const int *end = p + n;       /* one past the last reading */
    while (p < end)
        total += *p++;            /* read, then move to the next */
    return total;
}

