void reverse(int *a, int n)
{
    if (n < 2) return;            /* nothing to swap */
    int *lo = a;
    int *hi = a + n - 1;
    while (lo < hi) {
        int t = *lo;
        *lo = *hi;
        *hi = t;
        lo++;
        hi--;
    }
}
